function veloraGetLang() {
  try {
    var stored = localStorage.getItem(VELORA_I18N_STORAGE_KEY);
    if (stored && VELORA_SUPPORTED_LANGS.indexOf(stored) !== -1) return stored;
  } catch (e) { /* geen opslag beschikbaar — val terug op standaardtaal */ }
  return 'nl';
}

function veloraSetLang(lang) {
  if (VELORA_SUPPORTED_LANGS.indexOf(lang) === -1) return;
  try { localStorage.setItem(VELORA_I18N_STORAGE_KEY, lang); } catch (e) { /* geen opslag beschikbaar */ }
  veloraApplyTranslations(lang);
}

// Haalt een geneste waarde op zoals "footer.linkContact" -> VELORA_TRANSLATIONS[lang].footer.linkContact
function veloraTranslate(key, lang) {
  lang = lang || veloraGetLang();
  var dict = VELORA_TRANSLATIONS[lang] || VELORA_TRANSLATIONS.nl;
  var parts = key.split('.');
  var value = dict;
  for (var i = 0; i < parts.length; i++) {
    if (value && typeof value === 'object' && parts[i] in value) {
      value = value[parts[i]];
    } else {
      // Ontbrekende sleutel in de gekozen taal -> terugvallen op Nederlands
      // i.p.v. een lege/kapotte tekst te tonen.
      var fallback = VELORA_TRANSLATIONS.nl;
      for (var j = 0; j < parts.length; j++) {
        if (fallback && typeof fallback === 'object' && parts[j] in fallback) fallback = fallback[parts[j]];
        else return key;
      }
      return fallback;
    }
  }
  return value;
}

function veloraApplyTranslations(lang) {
  lang = lang || veloraGetLang();
  document.documentElement.setAttribute('lang', lang);

  document.querySelectorAll('[data-i18n]').forEach(function (el) {
    var key = el.getAttribute('data-i18n');
    var translated = veloraTranslate(key, lang);
    var attr = el.getAttribute('data-i18n-attr');
    if (attr) {
      el.setAttribute(attr, translated);
    } else {
      el.textContent = translated;
    }
  });

  // Taalwisselaar-knop zelf bijwerken (vlag + naam van de huidige taal)
  var meta = VELORA_LANG_META[lang];
  var flagEl = document.getElementById('langCurrentFlag');
  var nameEl = document.getElementById('langCurrentName');
  if (flagEl && meta) flagEl.textContent = meta.flag;
  if (nameEl && meta) nameEl.textContent = meta.name;

  document.querySelectorAll('.lang-dropdown button[data-lang]').forEach(function (btn) {
    btn.classList.toggle('is-active', btn.getAttribute('data-lang') === lang);
  });
}

document.addEventListener('DOMContentLoaded', function () {
  veloraApplyTranslations(veloraGetLang());

  var toggle = document.getElementById('langSwitcherToggle');
  var dropdown = document.getElementById('langDropdown');
  if (toggle && dropdown) {
    function setDropdownOpen(isOpen) {
      dropdown.classList.toggle('is-open', isOpen);
      toggle.setAttribute('aria-expanded', String(isOpen));
    }

    toggle.addEventListener('click', function (e) {
      e.stopPropagation();
      setDropdownOpen(!dropdown.classList.contains('is-open'));
    });

    dropdown.querySelectorAll('button[data-lang]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        veloraSetLang(btn.getAttribute('data-lang'));
        setDropdownOpen(false);
        toggle.focus();
      });
    });

    document.addEventListener('click', function (e) {
      if (dropdown.classList.contains('is-open') && !e.target.closest('.lang-switcher')) {
        setDropdownOpen(false);
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && dropdown.classList.contains('is-open')) {
        setDropdownOpen(false);
        toggle.focus();
      }
    });
  }
});
